def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # The non-background, non-marker pattern is the object to replicate.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    marker_color = min((v for v in counts if v != bg), key=lambda v: counts[v])

    # Find the compact pattern made of the remaining colors.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, marker_color)]
    if not cells:
        return out
    r0 = min(r for r, c, v in cells)
    r1 = max(r for r, c, v in cells)
    c0 = min(c for r, c, v in cells)
    c1 = max(c for r, c, v in cells)
    pattern = [(r-r0, c-c0, v) for r, c, v in cells]

    # Markers indicate the center of the pattern's bounding box.
    mr, mc = (r1-r0)//2, (c1-c0)//2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color:
                top, left = r-mr, c-mc
                for dr, dc, v in pattern:
                    rr, cc = top+dr, left+dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = v
    return out
